// @target: es2015
declare function dec(...args: any[]): any; declare let o: any, arr: any, k: any, x: any, a: any, b: any;
@dec class C { @dec m() {} @dec x = 1; @dec static accessor #y = 2; }

// @target: es2022
declare function dec(...args: any[]): any; declare let o: any, arr: any, k: any, x: any, a: any, b: any;
@dec class C extends Base { @dec m() {} static a = super.x; @dec accessor b = 1; }
declare class Base { static x: any; static y: any; static d: any; static m(): any; }

// @target: esnext
declare function dec(...args: any[]): any; declare let o: any, arr: any, k: any, x: any, a: any, b: any;
@dec class C { @dec accessor x = 1; @dec #m() {} }

// @target: esnext
// @useDefineForClassFields: false
declare function dec(...args: any[]): any; declare let o: any, arr: any, k: any, x: any, a: any, b: any;
@dec class C { @dec accessor x = 1; @dec #m() {} }

// @target: es2015
// @module: commonjs
declare function dec(...args: any[]): any; declare let o: any, arr: any, k: any, x: any, a: any, b: any;
export default @dec class { @dec static m() {} }

// @target: es2022
// @module: esnext
declare function dec(...args: any[]): any; declare let o: any, arr: any, k: any, x: any, a: any, b: any;
export @dec class C { @dec static x = 1; }

// @target: es2017
declare function dec(...args: any[]): any; declare let o: any, arr: any, k: any, x: any, a: any, b: any;
const C = @dec class { @dec async m() { await 1; } static { this.m; } };
